from typing import List

class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        res = 0
        pref = {}
        pref2 = {}

        for a in nums:
            for i in range(32):  # Assuming 32 bits for the integers
                p = a >> i
                if p not in pref:
                    pref[p] = a
                    pref2[p] = a
                else:
                    pref[p] = min(pref[p], a)
                    pref2[p] = max(pref2[p], a)

        for x in pref:
            y = res ^ 1 ^ x
            if x >= y and y in pref:
                res |= 1

        return res

